const p = $json.body ?? $json;
const topic = String(p.topic ?? p.subject ?? 'Tema de estudio').trim();
const content = String(p.content ?? '').trim();
if (!content) throw new Error('Falta el material de estudio');
if (content.length > 15000) throw new Error('El material supera 15 000 caracteres');
const minutes = Math.max(20, Math.min(120, Number(p.minutes) || 50));
const sentences = content.split(/\n|[.!?](?:\s+|$)/).map(x => x.trim()).filter(x => x.length > 12);
const concepts = [...new Set((content.toLowerCase().match(/[a-záéíóúñü]{6,}/gi) || []).filter(w => !['porque','cuando','también','puede','desde','entre','sobre','hasta','tiene','estos','estas'].includes(w)))].slice(0, 8);
const focus = Math.round(minutes * 0.55);
const practice = Math.round(minutes * 0.30);
const review = minutes - focus - practice;
const questions = sentences.slice(0, 5).map((text, index) => ({ id: index + 1, question: `Explica con tus palabras: ${text}`, answerHint: concepts[index % Math.max(concepts.length, 1)] || 'idea principal' }));
return [{ json: { ok: true, workflow: 'coach-estudio', sessionId: `study-${Date.now().toString(36)}`, topic, minutes, createdAt: new Date().toISOString(), concepts, plan: [{ minutes: focus, phase: 'Comprender', technique: 'lectura activa y mapa mental' }, { minutes: practice, phase: 'Recordar', technique: 'explicación sin apuntes y ejemplos propios' }, { minutes: review, phase: 'Comprobar', technique: 'autoevaluación y corrección' }], questions, spacedRepetition: ['hoy al finalizar', 'mañana', 'en 3 días', 'en 7 días'], sourcePreview: content.slice(0, 240) } }];

const fs = require('fs');
const file = '/files/nexora-study.jsonl';
for (const item of items) fs.appendFileSync(file, `${JSON.stringify(item.json)}\n`, 'utf8');
return items.map(item => ({ json: { ...item.json, storedLocally: true, localFile: file, message: 'Plan adaptativo y repaso espaciado creados' } }));
